#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const ll MOD = 1000000007;

ll add(ll x, ll y) {
    x += y;
    if (x >= MOD) x -= MOD;
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    vector<ll> dp1(n + 1, 0), dp2(n + 1, 0);
    vector<ll> s;

    dp1[0] = 1;
    s.push_back(1);

    for (ll i = 1; i <= 2 * n; ++i) {
        fill(dp2.begin(), dp2.end(), 0);

        for (ll j = 0; j <= n; ++j) {
            if (j > 0) {
                dp2[j - 1] = add(dp2[j - 1], dp1[j]);
                if (j <= 2 * n - (i + 1))
                    dp2[j + 1] = add(dp2[j + 1], dp1[j]);
            } else {
                dp2[1] = add(dp2[1], dp1[0]);
            }
        }

        ll sum = 0;
        for (ll j = 0; j <= n; ++j)
            sum = add(sum, dp2[j]);

        dp1.swap(dp2);
        s.push_back(sum);
    }

    ll answer = 0;
    for (ll i = 1; i < 2 * n; i += 2)
        answer = add(answer, s[i]);

    cout << answer;
    return 0;
}

