int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    vector<ll> dp1(n + 1, 0), dp2(n + 1, 0);
    vector<ll> s;
    dp1[0] = 1;
    s.push_back(1);

    for (ll i = 1; i <= 2 * n; ++i) {
        fill(dp2.begin(), dp2.end(), 0);

        for (ll j = 0; j <= n; ++j) {
            if (j > 0) {
                dp2[j - 1] = (dp2[j - 1] + dp1[j]) % MOD;
                if (j <= 2 * n - (i + 1) && j + 1 <= n)
