        for (ll value : dp2)
            sum = (sum + value) % MOD;

        dp1.swap(dp2);
        s.push_back(sum);
    }

    ll answer = 0;
    for (ll i = 1; i < 2 * n; i += 2)
        answer = (answer + s[i]) % MOD;

    cout << answer;
    return 0;
